#!/usr/bin/env node

/**
 * Mock Deployment Orchestrator Server
 * 
 * This is a test server that simulates the deployment orchestrator.
 * It listens on http://localhost:47301/api/deploy-config
 * 
 * Usage:
 *   node mock_orchestrator.js
 */

const http = require('http');
const fs = require('fs');
const path = require('path');

const PORT = 47301;
const HOST = 'localhost';
const LOG_FILE = path.join(__dirname, 'deployment_audit.log');

// Initialize log file
if (!fs.existsSync(LOG_FILE)) {
    fs.writeFileSync(LOG_FILE, `Deployment Audit Log Started: ${new Date().toISOString()}\n`);
}

/**
 * Log deployment to audit file
 */
function logDeployment(config) {
    const entry = {
        timestamp: new Date().toISOString(),
        project: config.project,
        deploymentTimestamp: config.timestamp,
        variableCount: Object.keys(config.variables).length,
        variables: Object.keys(config.variables),
        status: 'ACCEPTED'
    };

    fs.appendFileSync(LOG_FILE, JSON.stringify(entry, null, 2) + '\n');
    console.log(`[${entry.timestamp}] Deployment logged for project: ${config.project}`);
}

/**
 * Validate configuration
 */
function validateConfig(config) {
    const errors = [];

    if (!config.project) {
        errors.push('Missing project name');
    }

    if (!config.timestamp) {
        errors.push('Missing deployment timestamp');
    }

    if (!config.variables || typeof config.variables !== 'object') {
        errors.push('Missing or invalid variables object');
    } else {
        // Check for common required variables
        const requiredVars = ['NODE_ENV', 'DATABASE_URL'];
        const missingVars = requiredVars.filter(v => !(v in config.variables));

        if (missingVars.length > 0) {
            errors.push(`Missing required variables: ${missingVars.join(', ')}`);
        }
    }

    return errors;
}

/**
 * Generate deployment ID
 */
function generateDeploymentId() {
    const timestamp = Date.now();
    const random = Math.random().toString(36).substring(2, 8).toUpperCase();
    return `DEPLOY-${timestamp}-${random}`;
}

/**
 * Handle requests
 */
const server = http.createServer((req, res) => {
    console.log(`${req.method} ${req.url}`);

    // CORS headers
    res.setHeader('Access-Control-Allow-Origin', '*');
    res.setHeader('Access-Control-Allow-Methods', 'POST, GET, OPTIONS');
    res.setHeader('Access-Control-Allow-Headers', 'Content-Type');

    if (req.method === 'OPTIONS') {
        res.writeHead(200);
        res.end();
        return;
    }

    if (req.method === 'POST' && req.url === '/api/deploy-config') {
        let body = '';

        req.on('data', chunk => {
            body += chunk.toString();
        });

        req.on('end', () => {
            try {
                const config = JSON.parse(body);

                // Validate configuration
                const validationErrors = validateConfig(config);

                if (validationErrors.length > 0) {
                    console.log(`❌ Validation failed: ${validationErrors.join(', ')}`);
                    res.writeHead(400, { 'Content-Type': 'application/json' });
                    res.end(JSON.stringify({
                        status: 'rejected',
                        errors: validationErrors,
                        message: 'Configuration validation failed'
                    }));
                    return;
                }

                // Accept configuration
                const deploymentId = generateDeploymentId();
                logDeployment(config);

                console.log(`✓ Config accepted for project: ${config.project}`);

                res.writeHead(200, { 'Content-Type': 'application/json' });
                res.end(JSON.stringify({
                    status: 'accepted',
                    deploymentId: deploymentId,
                    project: config.project,
                    timestamp: config.timestamp,
                    message: 'Configuration accepted and logged',
                    auditLog: LOG_FILE
                }));
            } catch (err) {
                console.error(`❌ JSON parsing error: ${err.message}`);
                res.writeHead(400, { 'Content-Type': 'application/json' });
                res.end(JSON.stringify({
                    status: 'error',
                    message: 'Invalid JSON payload',
                    error: err.message
                }));
            }
        });
    } else if (req.url === '/api/deploy-config/audit' || req.url === '/audit') {
        // Serve the audit log
        if (fs.existsSync(LOG_FILE)) {
            res.writeHead(200, { 'Content-Type': 'text/plain' });
            res.end(fs.readFileSync(LOG_FILE, 'utf-8'));
        } else {
            res.writeHead(404, { 'Content-Type': 'application/json' });
            res.end(JSON.stringify({ error: 'Audit log not found' }));
        }
    } else if (req.url === '/health' || req.url === '/') {
        res.writeHead(200, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({
            status: 'operational',
            service: 'Mock Deployment Orchestrator',
            port: PORT,
            endpoints: {
                health: '/health',
                audit: '/audit',
                deployConfig: '/api/deploy-config'
            }
        }));
    } else {
        res.writeHead(404, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({
            status: 'error',
            message: 'Endpoint not found'
        }));
    }
});

server.listen(PORT, HOST, () => {
    console.log(`\n╔════════════════════════════════════════╗`);
    console.log(`║  Mock Deployment Orchestrator Started  ║`);
    console.log(`╚════════════════════════════════════════╝\n`);
    console.log(`Listening on: http://${HOST}:${PORT}`);
    console.log(`API Endpoint: POST http://${HOST}:${PORT}/api/deploy-config`);
    console.log(`Audit Log: ${LOG_FILE}`);
    console.log(`\nEndpoints:`);
    console.log(`  GET  /health                     - Health check`);
    console.log(`  POST /api/deploy-config          - Submit deployment config`);
    console.log(`  GET  /audit                      - View audit log\n`);
    console.log(`Press Ctrl+C to stop the server\n`);
});

server.on('error', (err) => {
    if (err.code === 'EADDRINUSE') {
        console.error(`Error: Port ${PORT} is already in use`);
        process.exit(1);
    }
    throw err;
});

